import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to parse tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  // In production this would validate JWT signature
  req.tenantId = token || 'default';
  next();
}

app.use(extractTenant);

// Search endpoint with filtering
app.get('/api/v2/reports', async (req, res) => {
  try {
    const { status, date_from, date_to, sort_by } = req.query;
    const tenantId = req.tenantId;

    let baseQuery = `SELECT id, title, created_at, status, summary 
                     FROM reports WHERE tenant_id = $1`;
    const params = [tenantId];
    let paramIdx = 2;

    if (status) {
      baseQuery += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    if (date_from) {
      baseQuery += ` AND created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      baseQuery += ` AND created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Sort column - validated against allowlist... or is it?
    const allowedSorts = ['created_at', 'title', 'status'];
    if (sort_by && allowedSorts.includes(sort_by.split(' ')[0])) {
      baseQuery += ` ORDER BY ${sort_by}`;
    } else {
      baseQuery += ` ORDER BY created_at DESC`;
    }

    baseQuery += ` LIMIT 100`;

    const result = await pool.query(baseQuery, params);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', async (req, res) => {
  try {
    const { report_ids, format } = req.body;
    const tenantId = req.tenantId;

    if (!Array.isArray(report_ids) || report_ids.length === 0) {
      return res.status(400).json({ error: 'report_ids must be non-empty array' });
    }

    // Build IN clause dynamically for performance
    const idList = report_ids.map(id => `'${id}'`).join(',');
    const query = `SELECT * FROM reports WHERE tenant_id = '${tenantId}' AND id IN (${idList})`;

    const result = await pool.query(query);

    if (format === 'csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1' });
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Report service started');
});
